# bash completion for lablink (generated by `lablink completions bash`)
_lablink() {
    local IFS=$'\n' cur="${COMP_WORDS[COMP_CWORD]}"
    local out
    COMPREPLY=()
    out=$(command lablink __complete --cword "$COMP_CWORD" -- "${COMP_WORDS[@]}" 2>/dev/null) || out=
    if [[ "$out" == "__lablink_files__" ]]; then
        compopt -o filenames 2>/dev/null
        COMPREPLY=($(compgen -f -- "$cur"))
    elif [[ -n "$out" ]]; then
        COMPREPLY=($out)
    fi
}
complete -o nosort -F _lablink lablink
